import{_ as l,o as a,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Non disruptive data migration between pools","description":"","frontmatter":{"title":"Non disruptive data migration between pools","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","OSD","PG","存储集群","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Non_disruptive_data_migration_between_pools.md","filePath":"posts/2026/Non_disruptive_data_migration_between_pools.md","lastUpdated":null}'),r={name:"posts/2026/Non_disruptive_data_migration_between_pools.md"};function e(n,o,s,p,d,h){return a(),t("div",null,[...o[0]||(o[0]=[i('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由 IBM 的 Tom Solers 和 Bill Scales 主讲，介绍了他们正在开发的 Ceph pool migration（存储池迁移）特性，旨在实现完全无中断地将数据从一个 pool 迁移到另一个 pool，解决集群生命周期中存储配置无法灵活变更的痛点。</p><h2 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to &quot;背景与问题&quot;">​</a></h2><p>在 Ceph 集群的实际运营中，用户往往在部署初期根据当时的需求选定 pool 类型（replica pool 或 EC pool）、Erasure Code 的 K/M 参数等固定配置。随着业务发展，这些&quot;Day 1&quot;决策会逐渐与实际需求产生偏差：</p><ul><li>新增工作负载导致存储需求变化</li><li>需要从 replica pool 切换到 EC pool 以降低存储开销</li><li>需要将 EC profile 从 2+2 升级为 6+2 以适应更大规模</li><li>PG 数量不再适配数据量</li></ul><p>现有的手动迁移方式（创建新 pool、手动搬运数据）虽然基本可行，但流程繁琐、容易出错，且往往在迁移开始或结束时存在短暂中断。</p><h2 id="解决方案-pool-migration" tabindex="-1">解决方案：Pool Migration <a class="header-anchor" href="#解决方案-pool-migration" aria-label="Permalink to &quot;解决方案：Pool Migration&quot;">​</a></h2><p>Pool migration 提供了一种<strong>全自动、零停机</strong>的方式，将对象从源 pool 迁移到目标 pool，同时允许变更固定参数。核心特性：</p><ul><li><strong>单命令触发</strong>：通过扩展 <code>ceph osd pool create</code> 命令，新增 <code>--migrate-from-pool</code> 参数即可发起迁移</li><li><strong>完全无中断</strong>：迁移期间业务 IO 持续正常运行，无需安排维护窗口</li><li><strong>迁移进度可观测</strong>：直接通过 <code>ceph status</code> 查看迁移状态</li></ul><h2 id="技术实现" tabindex="-1">技术实现 <a class="header-anchor" href="#技术实现" aria-label="Permalink to &quot;技术实现&quot;">​</a></h2><h3 id="基于-watermark-的对象迁移机制" tabindex="-1">基于 Watermark 的对象迁移机制 <a class="header-anchor" href="#基于-watermark-的对象迁移机制" aria-label="Permalink to &quot;基于 Watermark 的对象迁移机制&quot;">​</a></h3><p>迁移以 PG 为基本单元进行，每个 PG 内的对象按 CRUSH rule 分配的 hash 值升序迁移：</p><ol><li><p><strong>Watermark（水位线）</strong>：每个 OSD 存储一个 watermark 来追踪迁移进度</p><ul><li>watermark 以下的对象已完成迁移（存储于目标 pool）</li><li>watermark 以上的对象尚未迁移（仍在源 pool）</li><li>OSD 依据 watermark 将 IO 请求重定向到正确的 pool</li></ul></li><li><p><strong>客户端缓存 Watermark</strong>：客户端缓存 watermark，用于预判 IO 应发送至哪个 pool</p><ul><li>若客户端缓存过期导致 IO 发送到错误 pool，OSD 会拒绝该 IO 并返回最新 watermark</li><li>客户端使用更新后的 watermark 重试，整个过程对上层应用透明</li><li>重定向 IO 占比极低，约为总量的 1%</li></ul></li><li><p><strong>数据安全保障</strong>：</p><ul><li>对象仅在写入目标 pool <strong>完全确认</strong>后才从源 pool 删除</li><li>watermark 仅在删除完成后才推进</li><li>保证对象在任意时刻都存在于源或目标 pool 之一，不存在数据丢失风险</li><li>OSD 崩溃后 watermark 持久化，迁移可恢复继续</li><li>网络故障通过标准重试机制处理</li><li>Peering 重启时 watermark 防止重复迁移</li></ul></li><li><p><strong>迁移级联（Migration Cascade）</strong>：迁移完成后，源 pool 变为一个空的 stub pool，仅负责将 IO 重定向到目标 pool。目标 pool 可作为下一次迁移的源，形成迁移级联链，确保历史 IO 不丢失。删除级联中任意一个 pool 会删除整个级联。</p></li></ol><h3 id="并发控制与优先级" tabindex="-1">并发控制与优先级 <a class="header-anchor" href="#并发控制与优先级" aria-label="Permalink to &quot;并发控制与优先级&quot;">​</a></h3><p>Pool migration 被设计为<strong>后台任务</strong>，核心目标是在不影响生产 IO 的前提下完成迁移：</p><ul><li>支持多个 PG 并发迁移，预计并发比例约为 <strong>5%</strong> 的 PG 同时迁移（仍在调优中）</li><li>与 backfill 和 recovery 机制类似，OSD 会根据自身负载决定是否执行迁移</li><li><strong>优先级</strong>：backfill/recovery &gt; pool migration，当需要恢复数据冗余时迁移自动暂停</li><li>迁移速度可通过与 backfill/recovery 相同的配置参数进行调控</li></ul><h3 id="不同-pg-数量的处理" tabindex="-1">不同 PG 数量的处理 <a class="header-anchor" href="#不同-pg-数量的处理" aria-label="Permalink to &quot;不同 PG 数量的处理&quot;">​</a></h3><p>支持源 pool 与目标 pool PG 数量不同的迁移场景：</p><ul><li><strong>PG 数量相同</strong>（推荐）：每个源 PG 一对一迁移到目标 PG</li><li><strong>目标 PG 更多（PG 分裂）</strong>：源 PG 按 hash 顺序分两段分别迁移到两个目标 PG，先完成前半段再进行后半段</li><li><strong>目标 PG 更少（PG 合并）</strong>：多个源 PG 依次（非并发）迁移到同一目标 PG，可能限制并发迁移 PG 的数量</li><li>迁移进行期间不支持修改 PG 数量，迁移完成后恢复正常的 PG 增减操作</li></ul><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li>代码已全部编写完成，Pull Request 已提交，但<strong>尚未合并到 main 分支</strong></li><li>大部分测试已通过，仍有少量测试需要修复</li><li>在 Teuthology 上游测试环境中进行了大量扩展测试，覆盖错误注入、各类组合场景</li><li>预计<strong>一个月内</strong>可以合并到 main 分支</li></ul><h2 id="暂不支持的场景" tabindex="-1">暂不支持的场景 <a class="header-anchor" href="#暂不支持的场景" aria-label="Permalink to &quot;暂不支持的场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>Cache Tiering</td><td>该特性已处于 deprecated 状态，不计划支持</td></tr><tr><td>OSD 去重（deduplication）</td><td>功能尚不完整，暂无支持计划</td></tr><tr><td>Crimson OSD</td><td>计划后续支持，工作量不大但尚未完成</td></tr><tr><td>replica pool → 老式 EC pool</td><td>老式 EC pool 不支持 omap 等特性，迁移前需加入检查拦截，防止迁移中途失败</td></tr></tbody></table><h2 id="后续计划" tabindex="-1">后续计划 <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;后续计划&quot;">​</a></h2><ul><li>继续完善测试，修复 Teuthology 测试基础设施中的剩余问题</li><li>增加迁移前的合法性校验（policing checks），例如检测目标 pool 是否支持源 pool 的所有特性</li><li>完善用户界面交互体验</li><li>后续添加 Crimson OSD 支持</li><li>代码合并 main 后，推进生产环境落地</li></ul>',25)])])}const c=l(r,[["render",e]]);export{g as __pageData,c as default};
